def copy_admin_permissions_to_account_permissions(
    apps,
    schema_editor,
):
    Group = apps.get_model("auth", "Group")
    Permission = apps.get_model("auth", "Permission")
    ContentType = apps.get_model("contenttypes", "ContentType")
    db_alias = schema_editor.connection.alias
    # 获取 Account 模型对应的 ContentType
    account_content_type, _ = ContentType.objects.using(db_alias).get_or_create(
        app_label="app01",
        model="account",
    )
    for old_codename, (new_codename, new_name) in PERMISSION_MAP.items():
        # 查找旧Admin权限
        old_permission = (
            Permission.objects.using(db_alias)
            .filter(
                content_type__app_label="app01",
                content_type__model="admin",
                codename=old_codename,
            )
            .first()
        )

        # 确保新Account权限存在
        new_permission, _ = Permission.objects.using(db_alias).get_or_create(
            content_type=account_content_type,
            codename=new_codename,
            defaults={"name": new_name},
        )

        # 旧权限不存在时，无需迁移对应的角色授权
        if old_permission is None:
            continue

        # 找到拥有旧权限的角色
        groups = (
            Group.objects.using(db_alias)
            .filter(
                permissions=old_permission,
            )
            .distinct()
        )

        # 将新权限增加到这些角色中
        for group in groups:
            group.permissions.add(new_permission)


